import 'package:drift/drift.dart';
import '../app_database.dart';
import '../tables/patients_table.dart';

part 'patient_dao.g.dart';

@DriftAccessor(tables: [Patients, PatientAllergies, PatientConditions])
class PatientDao extends DatabaseAccessor<AppDatabase> with _$PatientDaoMixin {
  PatientDao(super.db);

  // Queries will be generated by drift_dev
  // Soft-deleted rows (deletedAt set) are never returned.
  Future<List<Patient>> getAllPatients() =>
      (select(patients)..where((p) => p.deletedAt.isNull())).get();
  Future<Patient?> getPatientById(int id) => (select(patients)
        ..where((p) => p.id.equals(id) & p.deletedAt.isNull()))
      .getSingleOrNull();

  /// Looks up a patient by file number, including soft-deleted rows.
  ///
  /// Demo seeders use this so a deleted demo patient is neither resurrected nor
  /// re-inserted against the unique file-number constraint.
  Future<Patient?> getPatientByFileNumber(String fileNumber) =>
      (select(patients)..where((p) => p.fileNumber.equals(fileNumber)))
          .getSingleOrNull();

  /// Highest numeric file number, including soft-deleted rows.
  ///
  /// File numbers have a unique constraint across every row, so new files must
  /// skip numbers reserved by deleted patients.
  Future<int?> getMaxNumericFileNumber() async {
    final row = await customSelect(
      'SELECT MAX(CAST(file_number AS INTEGER)) AS max_file FROM patients',
      readsFrom: {patients},
    ).getSingle();
    return row.readNullable<int>('max_file');
  }

  Future<int> insertPatient(PatientsCompanion entry) => into(patients).insert(entry);
  Future<bool> updatePatient(PatientsCompanion entry) => update(patients).replace(entry);
  Future<int> softDeletePatient(int id) {
    return (update(patients)..where((p) => p.id.equals(id))).write(
      PatientsCompanion(deletedAt: Value(DateTime.now())),
    );
  }

  Future<List<Patient>> searchPatients(String query) => (select(patients)
        ..where((p) =>
            p.deletedAt.isNull() &
            (p.fullName.contains(query) |
                p.searchText.contains(query) |
                p.phone.contains(query) |
                p.fileNumber.contains(query))))
      .get();

  Future<List<PatientAllergy>> getPatientAllergies(int patientId) =>
      (select(patientAllergies)..where((a) => a.patientId.equals(patientId))).get();
  Future<int> insertAllergy(PatientAllergiesCompanion entry) => into(patientAllergies).insert(entry);
  Future<int> deleteAllergy(int id) => (delete(patientAllergies)..where((a) => a.id.equals(id))).go();

  Future<List<PatientCondition>> getPatientConditions(int patientId) =>
      (select(patientConditions)..where((c) => c.patientId.equals(patientId))).get();
  Future<int> insertCondition(PatientConditionsCompanion entry) => into(patientConditions).insert(entry);
  Future<int> deleteCondition(int id) => (delete(patientConditions)..where((c) => c.id.equals(id))).go();
}
